def process_orders(orders):
    total = 0
    failed = []
    for o in orders:
        oid = o['id']
        try:
            q = o['quantity']
            a = o['amount']
            if not isinstance(q, int) or not isinstance(a, (int, float)):
                failed.append(oid)
                continue
            total += a * q
        except Exception:
            pass
    return {"revenue": total, "failed_orders": failed}
